      printf("[DumpLv] begin screen=%p\n", (void *)lv_screen_active());
      fflush(stdout);
      g_dump_status = ui_obj_dump_do();
      printf("[DumpLv] done status=%d\n", g_dump_status);
      fflush(stdout);
      g_dump_done = 1;
