static void gt911_touch_event(struct gt911_dev_s *dev)
{
  struct gt911_data_s *data = (struct gt911_data_s *)dev->buffer;
  struct gt911_touchpoint_s *tp = data->touchpoint;

  /* 关键机制（NuttX touchscreen upper 层）：
   *   touch_event() 按 sample->npoints 写入队列（circbuf 元素大小 =
   *   SIZEOF_TOUCH_SAMPLE_S(maxpoint)），LVGL 端 read() 期望一次读满
   *   SIZEOF_TOUCH_SAMPLE_S(maxpoint) 字节。
   * 若 npoints 小于 maxpoint，队列元素写不满、LVGL 判定"读不完整"
   * 而忽略所有触摸！因此必须用 maxpoint 大小的缓冲区构造 sample，
   * npoints = GT911_TOUCHPOINTS(=maxpoint)，有效点填 point[0]，
   * 其余点 flags=0（无效，LVGL 跳过）。 */

  uint8_t sample_buf[SIZEOF_TOUCH_SAMPLE_S(GT911_TOUCHPOINTS)];
  struct touch_sample_s *sample =
    (struct touch_sample_s *)sample_buf;
  struct touch_point_s *point = sample->point;

  memset(sample_buf, 0, sizeof(sample_buf));
  sample->npoints = GT911_TOUCHPOINTS;

  /* 坐标方向适配：GT911 传感器原生 320×480（竖屏）坐标，
   * 面板为 480×320 横屏（LANDSCAPE+MV=1）。
   * 交换 X/Y 并对 Y 翻转，映射到 LVGL 的 480×320 坐标系。
   * 若方向仍不对，调整这里的交换/翻转组合（4 种）：
   *   横屏映射 = (x,y) → (319-y, x)    或 (y, x)
   *            = (319-y, 479-x)        或 (y, 479-x)
   * 当前采用 (x,y)→(y, 319-x) 变体，按实机微调。 */

  point->x         = tp->y;
  point->y         = 319 - tp->x;
  point->pressure  = tp->pressure;
  point->flags     = TOUCH_POS_VALID | TOUCH_PRESSURE_VALID;

  if (data->buffer_status)
    {
      point->flags |= TOUCH_DOWN;
      dev->has_report = true;

      /* ⚠️ 2026-08-21：删掉 [Touch] down 调试 printf——每个触摸事件都打印
