  timeout_ms = cycles * 700 + 20000;

  for (waited = 0; waited < timeout_ms; waited += 100)
    {
      if (ui_app_tsim_left() < 0)
        {
          printf("[SynTap] completed cycles=%d\n", cycles);
          return 0;
