+static int cmd_tsim(int argc, char *argv[])
+{
+  int cycles;
+  int timeout_ms;
+  int waited;
+
+  if (argc < 3)
+    {
+      printf("Usage: plant tsim <cycles> | stop | status\n");
+      return -1;
