import numpy as np, wave, os
from collections import Counter
BASE=os.path.join(os.environ['TEMP'],'plantfix')
w=wave.open(os.path.join(BASE,'rec_export.wav'),'rb'); fs=w.getframerate(); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(np.float64); w.close()
def events(a,b,thr):
    s=d[int(a*fs):int(b*fs)]
    # find local maxima above thr in abs
    idx=np.where(np.abs(s)>thr)[0]
    gr=[]
    for i in idx:
        if gr and i-gr[-1][-1]<=8: gr[-1].append(i)
        else: gr.append([i])
    pos=[]
    for g in gr:
        seg=np.abs(s[g])
        k=int(g[np.argmax(seg)])
        pos.append(k)
    return np.array(pos)+int(a*fs)
for (a,b) in [(3.00,4.35),(0.25,0.34),(2.60,3.00)]:
    for thr in [600,900]:
        pk=events(a,b,thr)
        if len(pk)<2: 
            print(f'{a}-{b}s thr{thr}: none'); continue
        sp=np.diff(pk)
        print(f'{a}-{b}s thr{thr}: n={len(pk)} spacing min={sp.min()} max={sp.max()} mean={sp.mean():.2f} std={sp.std():.2f}')
        print('   uniq spacing:', Counter(sp.tolist()).most_common(6))
        res=pk%980
        print('   residues mod980:', Counter(res.tolist()).most_common(4))
