  if (st.fp != NULL) fclose(st.fp);

  if (ret < 0)
    {
      printf("[Cam] capture failed: %d\n", ret);
      return ret;
    }

  if (st.total == 0)
    {
      printf("[Cam] no data received (0 bytes)\n");
      return -ENODATA;
    }

  if (out_len != NULL)
    {
      *out_len = st.total;
    }

