int lcd_put_rgb565(const uint8_t *fb, int sw, int sh,
                   int dx, int dy, int dw, int dh)
{
  int fd = open("/dev/lcd0", O_WRONLY);
  uint8_t rowbuf[640];      /* 一块最大 320 像素 × 2B（见下方越界说明） */
  struct lcddev_area_s area;
  static int16_t s_sx0[480];   /* 目标 x → 源整数 x0（双线性权重表，static） */
  static uint8_t s_fx8[480];   /* 目标 x → 源小数权重 ×256 */
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  memset(&area, 0, sizeof(area));
  area.stride = 0;

  /* 预计算 x 方向双线性权重（每帧一次，dw+dh 次整数除法） */

  {
    int x;

    for (x = 0; x < dw; x++)
      {
        int pos = x * sw;
        int s0 = pos / dw;
        int f = pos % dw;

        s_sx0[x] = (int16_t)(s0 >= sw ? sw - 1 : s0);
        s_fx8[x] = (uint8_t)((f * 256) / dw);
      }
  }

  for (y = 0; y < dh; y++)
    {
      int vpos = y * sh;
      int sy0 = vpos / dh;
      int fy = vpos % dh;
      int sy1;
      int fy8;
      int x0;

      if (sy0 >= sh)
        {
          sy0 = sh - 1;
        }

      sy1 = (sy0 + 1 >= sh) ? sy0 : sy0 + 1;
      fy8 = (fy * 256) / dh;

      /* 每行分块写（每块 ≤320 像素 = 640B）。
       *
       * 越界背景（CAMERA_DEBUG_LOG 2.46/2.47）：st7789 非 3WIRE 路径的
       * 字节交换缓冲 rowbuff_be 只有 ST7789_XRES×2 = 640B（map 实测
       * 0x3fcb96a0, 0x280）。而横屏 480 宽的一行是 960B —— 整行一次
       * PUTAREA 时 wrram 的交换循环把整行数据写进 640B 缓冲，越界
       * 320B/行 横扫 .bss（紧邻的 shutdown_handlers / g_cam_quiet /
       * g_cam_byte_swap / g_cam_rxbuf 0x3fcb9920 起全部被覆写）→
       * swap 标志随机翻转、rxbuf 帧头被毁、quiet 失效。
       * 面板数据恰好自洽（交换循环先写越界区再 SPI_SNDBLOCK 读回），
       * 所以画面"看起来正常"，内存却在被悄悄破坏 —— 之前 swap 矛盾
       * （set_swap(false) 后 capture 打印 swap=on）就是它干的。
       * 约束：st7789.c / defconfig XRES/YRES 不动 → 只能调用方规避：
       * 每块 ≤ 320 像素，保证 wrram 交换不超 640B。 */

      for (x0 = 0; x0 < dw; x0 += 320)
        {
          int chunk = dw - x0;
          int x;

          if (chunk > 320)
            {
              chunk = 320;
            }

          for (x = 0; x < chunk; x++)
            {
              int t = x0 + x;
              int sx0 = s_sx0[t];
              int fx = s_fx8[t];
              int sx1 = (sx0 + 1 >= sw) ? sx0 : sx0 + 1;
              int w00;
              int w01;
              int w10;
              int w11;
              uint16_t p00;
              uint16_t p01;
              uint16_t p10;
              uint16_t p11;
              int r;
              int g;
              int b;
              uint16_t px;

              /* 2×2 邻域（LE RGB565），角点先做源帧锐化（unsharp）再双线性：
               * 放大发虚由锐化补偿 —— 清晰度正解（分辨率受无 PSRAM 硬约束） */

              p00 = cam_sharp_px(fb, sw, sh, sx0, sy0);
              p01 = cam_sharp_px(fb, sw, sh, sx1, sy0);
              p10 = cam_sharp_px(fb, sw, sh, sx0, sy1);
              p11 = cam_sharp_px(fb, sw, sh, sx1, sy1);

              /* 双线性权重（256 定点；w00+w01+w10+w11 = 65536） */

              w00 = (256 - fx) * (256 - fy8);
              w01 = fx * (256 - fy8);
              w10 = (256 - fx) * fy8;
              w11 = fx * fy8;

              /* 逐通道 2×2 加权平均（R5/G6/B5 分开插值，防色偏） */

              r = ((((p00 >> 11) & 31) * w00 + ((p01 >> 11) & 31) * w01 +
                    ((p10 >> 11) & 31) * w10 + ((p11 >> 11) & 31) * w11) >> 16);
              g = ((((p00 >> 5) & 63) * w00 + ((p01 >> 5) & 63) * w01 +
                    ((p10 >> 5) & 63) * w10 + ((p11 >> 5) & 63) * w11) >> 16);
              b = (((p00 & 31) * w00 + (p01 & 31) * w01 +
                    (p10 & 31) * w10 + (p11 & 31) * w11) >> 16);

              px = (uint16_t)((r << 11) | (g << 5) | b);
              rowbuf[x * 2]     = (uint8_t)(px & 0xff);
              rowbuf[x * 2 + 1] = (uint8_t)(px >> 8);
            }

          area.col_start = dx + x0;
          area.col_end = dx + x0 + chunk - 1;
          area.row_start = dy + y;
          area.row_end = dy + y;
          area.data = rowbuf;
          ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
        }
    }

  close(fd);
  return 0;
}

