{
  int fd = open("/dev/lcd0", O_WRONLY);
  struct lcddev_area_s area;
  static int16_t s_sx0[480];   /* target x -> source integer x0 (bilinear) */
  static uint8_t s_fx8[480];   /* target x -> source fraction x256 */
  uint8_t *fbuf;
  int y;

  if (fd < 0)
    {
      printf("[LCD] open /dev/lcd0 failed: %d\n", fd);
      return -1;
    }

  if (dw > 480)
    {
      dw = 480;
    }

  if (dw <= 0 || dh <= 0)
    {
      close(fd);
      return -1;
    }

  /* Whole-frame staging buffer: scale into one contiguous area, then a
   * single LCDDEVIO_PUTAREA pushes the whole viewport.  st7789 wrram
   * swaps/sends in rowbuff_be-sized chunks, so large areas are safe. */

  fbuf = malloc((size_t)dw * (size_t)dh * 2);
  if (fbuf == NULL)
    {
      printf("[LCD] malloc staging %dx%d failed\n", dw, dh);
      close(fd);
      return -1;
    }

  memset(&area, 0, sizeof(area));
  area.stride = 0;

  /* Precompute x bilinear weights once per frame (dw+d h integer divs) */

  {
    int x;

    for (x = 0; x < dw; x++)
      {
        int pos = x * sw;
        int s0 = pos / dw;
        int f = pos % dw;

        s_sx0[x] = (int16_t)(s0 >= sw ? sw - 1 : s0);
        s_fx8[x] = (uint8_t)((f * 256) / dw);
      }
  }

  for (y = 0; y < dh; y++)
    {
      int vpos = y * sh;
      int sy0 = vpos / dh;
      int fy = vpos % dh;
      int sy1;
      int fy8;
      int x0;
      uint8_t *dst = fbuf + (size_t)y * (size_t)dw * 2;

      if (sy0 >= sh)
        {
          sy0 = sh - 1;
        }

      sy1 = (sy0 + 1 >= sh) ? sy0 : sy0 + 1;
      fy8 = (fy * 256) / dh;

      for (x0 = 0; x0 < dw; x0++)
        {
          int sx0 = s_sx0[x0];
          int fx = s_fx8[x0];
          int sx1 = (sx0 + 1 >= sw) ? sx0 : sx0 + 1;
          int w00;
          int w01;
          int w10;
          int w11;
          uint16_t p00;
          uint16_t p01;
          uint16_t p10;
          uint16_t p11;
          int r;
          int g;
          int b;
          uint16_t px;

          p00 = cam_sharp_px(fb, sw, sh, sx0, sy0);
          p01 = cam_sharp_px(fb, sw, sh, sx1, sy0);
          p10 = cam_sharp_px(fb, sw, sh, sx0, sy1);
          p11 = cam_sharp_px(fb, sw, sh, sx1, sy1);

          w00 = (256 - fx) * (256 - fy8);
          w01 = fx * (256 - fy8);
          w10 = (256 - fx) * fy8;
          w11 = fx * fy8;

          r = ((((p00 >> 11) & 31) * w00 + ((p01 >> 11) & 31) * w01 +
                ((p10 >> 11) & 31) * w10 + ((p11 >> 11) & 31) * w11) >> 16);
          g = ((((p00 >> 5) & 63) * w00 + ((p01 >> 5) & 63) * w01 +
                ((p10 >> 5) & 63) * w10 + ((p11 >> 5) & 63) * w11) >> 16);
          b = (((p00 & 31) * w00 + (p01 & 31) * w01 +
                (p10 & 31) * w10 + (p11 & 31) * w11) >> 16);

          px = (uint16_t)((r << 11) | (g << 5) | b);
          dst[x0 * 2]     = (uint8_t)(px & 0xff);
          dst[x0 * 2 + 1] = (uint8_t)(px >> 8);
        }
    }

  area.col_start = dx;
  area.col_end = dx + dw - 1;
  area.row_start = dy;
  area.row_end = dy + dh - 1;
  area.data = fbuf;
  ioctl(fd, LCDDEVIO_PUTAREA, (unsigned long)&area);

  free(fbuf);
  close(fd);
  return 0;
}
