/****************************************************************************
 * arch/xtensa/src/esp32s3/esp32s3_cam_dvp.h
 *
 * Public interface for the ESP32-S3 DVP camera capture driver
 * (LCD_CAM CAM input mode + GDMA RX, per-frame ISR re-arm).
