int esp32s3_cam_dvp_init(void);

/* Arm DMA RX chain and start CAM capture. */

int esp32s3_cam_dvp_start(void);

/* Stop CAM capture. */

int esp32s3_cam_dvp_stop(void);

/* Capture one complete RGB565 frame (vs_eof=1, one aligned frame per
 * VSYNC; sink is called once with CAM_FRAME_SIZE bytes).  Returns
 * CAM_FRAME_SIZE on success, or negated errno. */

