int voice_service_talk(int seconds)
{
  pthread_t tid;
  pthread_attr_t attr;
  int ret;

  if (seconds < 1)
    {
      seconds = 1;
    }

  if (seconds > AI_VOICE_MAX_SECONDS)
    {
